// Helper function to count integers in the input sequence
function CountInt(values: seq<object>): int
    reads values
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= count <= i // Count of integers is non-negative and does not exceed the current index
        invariant i <= |values| // Index does not exceed the length of the input
    {
        if values[i] is int {
            count := count + 1; // Increment count if the current value is an integer
        }
        i := i + 1; // Move to the next element
    }
    count // Return the count of integers found
}
